TERROR.videos=[
{id:'film',title:'Terror – Ihr Urteil',kind:'Spielfilm · dein Dropbox-Link',url:'https://www.dropbox.com/scl/fi/10eucdtqordnka2oc3yxd/Terror-Ihr-Urteil.mp4?rlkey=op2miym54oft91o4bqy9tp3z3&st=un6q6rw4&dl=0',src:'https://www.dropbox.com/scl/fi/10eucdtqordnka2oc3yxd/Terror-Ihr-Urteil.mp4?rlkey=op2miym54oft91o4bqy9tp3z3&raw=1',before:'Wähle zuerst eine Textstelle. Formuliere eine Vermutung darüber, wie Kamera, Schauspiel oder Ton die Wahrnehmung einer Figur lenken könnten.',during:'Halte für drei Einstellungen Zeitmarke, Bildgrösse, Blickrichtung, Ton und Schnitt fest. Trenne die Beobachtung von ihrer Wirkung.',after:'Vergleiche mit dem Dramentext: Welche Deutung entsteht erst durch die Verfilmung? Belege sie mit einer Einstellung und einer Textstelle.',note:'Die bereitgestellte Fassung (93:37) wurde für die Szenenzuordnung lokal transkribiert; Übergänge wurden mit Textstellen und Filmbildern abgeglichen. Zehn didaktische Kapitel im Leseraum, beide Urteilsfassungen separat anwählbar. Eigene Ausschnitte lassen sich zusätzlich im Clipwerkzeug festlegen.'},
{id:'trolley',title:'«Strassenbahn» · Filosofix',kind:'SRF · Gedankenexperiment',youtube:'MhOJp1DcabM',url:'https://www.youtube.com/watch?v=MhOJp1DcabM',before:'Notiere deine erste Entscheidung im Dilemma-Labor, bevor du das Video ansiehst.',during:'Achte auf die Informationen, die das Experiment als sicher voraussetzt. Halte Zahlen, Optionen und ausgeschlossene Alternativen fest.',after:'Nenne drei Unterschiede zwischen dem Modell und der Lage in «Terror». Prüfe besonders Unsicherheit, staatliche Gewalt und Selbstrettung.',note:'Videotitel verifiziert. Die Aufgaben sind offene Sichtungsaufträge, keine Behauptungen über einzelne Einstellungen.'},
{id:'sommer',title:'TERROR · Sommers Weltliteratur',kind:'Kurzfassung · Medienvergleich',youtube:'rPRwu3J3-Ng',url:'https://sommers-weltliteratur.de/videos/terror-von-ferdinand-von-schirach/',before:'Lies mindestens eine Vernehmung im Original. Notiere, welche drei Details für ihre Deutung wesentlich sind.',during:'Protokolliere, was gekürzt, pointiert oder durch Figuren und Kommentar umgedeutet wird.',after:'Erstelle eine Liste: erhaltene Struktur / ausgelassene Ambivalenz / neu entstandene Wirkung. Entwirf eine eigene 90-Sekunden-Zusammenfassung mit Quellenhinweis.',note:'Werkseite und verknüpfte Video-ID geprüft. Enthält voraussichtlich Handlungs- und Schlussinformationen; für Erstlektüre bewusst einsetzen.'},
{id:'september',title:'Der 11. September 2001 und seine Folgen',kind:'MrWissen2go Geschichte | Terra X',youtube:'8cgWrmb1K54',start:325,url:'https://www.youtube.com/watch?v=8cgWrmb1K54&t=325s',before:'Unterscheide historischen Kontext und fiktiven Fall: «Terror» spielt nicht einfach die Ereignisse des 11. September nach.',during:'Beginne bei der von dir verlinkten Stelle 05:25. Notiere eine Tatsachenbehauptung, eine Erklärung und eine Bewertung mit Zeitmarken.',after:'Prüfe eine Behauptung am bpb-Beitrag. Erläutere dann, wie Sicherheitsdiskurse die Wahrnehmung von Bieglers Plädoyer verändern können.',note:'Titel und Anbieter über Videometadaten verifiziert. 05:25 stammt aus dem vorgegebenen Link; der Clip wurde nicht inhaltlich transkribiert.'}
];
TERROR.games=[
{name:'Urteilsweg & Argumente-Pingpong',url:'https://patrickfischerksa.github.io/terror_urteil_duell/',mode:'Urteilsweg allein · Duell zu zweit',before:'Bearbeite «Tat, Tatsache, Wertung» und eine Denkposition. Formuliere eine prüfbare Schlussregel.',during:'Achte darauf, welche Antworten die automatische Urteilstendenz beeinflussen. Im Duell: Beantworte das stärkste Gegenargument.',after:'Vergleiche das App-Ergebnis mit deiner eigenen Begründung. Welche normative Gewichtung steckt in den Regeln? Ein lokaler Regelscore ist kein juristisches Urteil und kein verlässlicher Nachweis der Qualität offener Texte.',verified:'Startseite und sichtbare Spielbeschreibung geprüft.'},
{name:'Verantwortungspoker: Terror',url:'https://patrickfischerksa.github.io/verhandlungspoker-terror/',mode:'Gruppenspiel · allein als Perspektivwechsel nutzbar',before:'Erstelle im Rollenlabor ein Profil. Unterscheide deine private Meinung von deiner Rollenpflicht.',during:'Protokolliere in einem Lagefenster, wer weiss, handeln kann, blockiert oder unterlässt. Allein bearbeitest du dieselbe Runde nacheinander aus mehreren Rollen.',after:'Prüfe, ob Abstimmungsgewichte und Sonderrechte Verantwortung sichtbar machen oder sie verzerren. Vergleiche mit der Evakuierungsfrage im Drama.',verified:'Sechs Rollen und dreizehn Lagefenster laut Spielbeschreibung. Der Handyweg überträgt Rollenpakete; keine Live-Kopplung.'},
{name:'Terror Games',url:'https://patrickfischerksa.github.io/terror_games/',mode:'Drei verknüpfte Spielwege',before:'Wähle bewusst zwischen Think Backwards, Choose Your Path und Jury-Simulation. Formuliere eine Lernfrage.',during:'Notiere eine Stelle, an der die angebotenen Optionen deinen Gedankengang lenken.',after:'Erfinde eine zusätzliche Option und erkläre, wie sie die Versuchsanordnung verändern würde.',verified:'Übersichtsseite und die drei Spieltitel geprüft; Unterspiele nicht vollständig durchgespielt.'},
{name:'TERROR · Quiz mit Sofortkorrektur',url:'https://patrickfischerksa.github.io/Terror_vonSchirach/terror_quiz_full.html',mode:'35 Fragen · Abrufwissen und Wiederholung',before:'Beantworte zunächst ohne Musterlösung. Ergänze bei jeder Antwort eine konkrete Textstelle.',during:'Prüfe verkürzte Antworten am Original. Bei Koch liegt ein Nicht-Abschuss-Befehl vor; «ohne klaren Befehl» ist dafür keine präzise Zusammenfassung.',after:'Wähle zwei Musterantworten und entwickle daraus differenzierte Absätze mit Beleg und Gegenbeleg. Automatische Textkorrektur ersetzt keine Interpretation.',verified:'35 sichtbare Fragen samt Musterantworten geprüft; inhaltliche Verkürzungen werden hier ausdrücklich nachgearbeitet.'}
];
TERROR.politics=[
{id:'sicherheit',title:'Freiheit und Sicherheit',intro:'Beide Begriffe können als Gegensätze auftreten. Sicherheit kann aber auch eine Bedingung für die Ausübung von Freiheit sein. Entscheidend sind die konkreten Mittel und Grenzen staatlichen Handelns.',tasks:['Vergleiche je eine Passage von Nelson und Biegler: Welche Freiheit soll für wen geschützt werden?','Entwirf zwei Massnahmen, die Sicherheit erhöhen sollen, ohne Unbeteiligte absichtlich zu töten. Prüfe ihre Grenzen.','Schreibe eine These, die nicht bei «mehr Sicherheit = weniger Freiheit» stehen bleibt.'],model:'Differenzierte Antworten benennen Schutzgüter, Betroffene, Eingriffstiefe, Wirksamkeit und Kontrolle. Sie behandeln Freiheit weder als Luxus noch Sicherheit als unbegrenzten Auftrag.',source:'folgen'},
{id:'ausnahme',title:'Die Sprache des Ausnahmezustands',intro:'Wer eine Lage als Krieg, Notfall oder alternativlos bezeichnet, verändert den Erwartungshorizont. Ob damit andere rechtliche Regeln gelten, ist eine gesonderte Frage.',tasks:['Untersuche Bieglers Kriegsrahmung auf PDF-S. 83–84. Welche Handlung erscheint dadurch notwendig?','Lies den verlinkten Debattenbeitrag und unterscheide Analyse von politischer Bewertung.','Verfasse einen Gegenkommentar, der eine reale Bedrohung anerkennt und dennoch die Normalisierung von Ausnahmen problematisiert.'],model:'Eine starke Analyse nennt die sprachliche Rahmung und prüft ihre Voraussetzungen. Sie bestreitet eine Gefahr nicht allein deshalb, weil deren politische Instrumentalisierung möglich ist.',source:'ausnahme'},
{id:'mehrheit',title:'Mehrheit, Minderheit, Rechtsstaat',intro:'Das Theaterpublikum kann über das Ende abstimmen. Das lädt zur Frage ein, worüber Mehrheiten entscheiden dürfen und welche Rechte gerade gegen Mehrheiten geschützt werden.',tasks:['Vergleiche Publikumsabstimmung, parlamentarische Gesetzgebung und gerichtliche Entscheidung. Was ist jeweils ihr Auftrag?','Erkläre, warum eine Mehrheit kein Beleg für die Gültigkeit einer moralischen Schlussregel ist.','Schreibe eine Stellungnahme: Macht die Abstimmung die Zuschauenden verantwortlich oder vereinfacht sie die Verantwortung?'],model:'Die Abstimmung ist künstlerisch wirksam, bildet aber ein rechtsstaatliches Verfahren nicht vollständig ab. Demokratische Legitimation und Grundrechtsbindung sind aufeinander bezogen, keine austauschbaren Prinzipien.',source:'gg1'},
{id:'weltbilder',title:'Weltanschauungen ohne Schubladen',intro:'Menschen können Würde religiös, humanistisch oder philosophisch begründen. Innerhalb derselben Tradition sind unterschiedliche Folgerungen möglich. Parteizugehörigkeit oder Religion bestimmt ein Urteil nicht automatisch.',tasks:['Entwickle zwei verschiedene Begründungen für die Unverfügbarkeit einer Person: eine religiös anschlussfähige und eine säkulare. Kennzeichne sie als deine Konstruktionen.','Vergleiche eine freiheitsorientierte, eine sicherheitsorientierte und eine fürsorgeorientierte Lesart. Benenne jeweils einen inneren Konflikt.','Prüfe: Kann jemand Koch moralisch verstehen und eine gesetzliche Abschussermächtigung trotzdem ablehnen?'],model:'Weltanschauliche Einbindung erklärt Prämissen, ohne Menschen auf Gruppenmeinungen festzulegen. Anerkennung gleicher Würde kann aus unterschiedlichen Überzeugungen entstehen. Eine Figur ist kein vollständiger Vertreter einer Weltanschauung.',source:'kant'},
{id:'propaganda',title:'Feindbilder lesen, Gegenrede entwickeln',intro:'Analysiere die Wirkung von Wir-Sie-Grenzen, Bedrohungsbehauptungen und Verallgemeinerungen. Eine fiktionale Täterrede ist keine Beschreibung einer Religionsgemeinschaft.',tasks:['Untersuche die im Stück wiedergegebene Drohung (PDF-S. 22) als Figurenrede. Wer spricht, wen beansprucht die Stimme zu vertreten, und mit welchem Recht?','Prüfe ein selbst formuliertes Beispiel: «Weil ein Täter sich auf eine Religion beruft, sind alle Angehörigen dieser Religion gefährlich.» Benenne den Fehlschluss.','Schreibe eine Gegenrede von 120 Wörtern: Benenne die Gewalt klar, vermeide Kollektivschuld und begründe einen gemeinsamen Rechtsmassstab.'],model:'Die didaktische Folge nach Roth lautet hier: aufmerksam werden, analytisch reflektieren, eine eigene begründete Position entwickeln. Die Übertragung auf «Terror» stammt aus dieser Lernumgebung. Religion, extremistische Ideologie und individuelle Tat sind auseinanderzuhalten.',source:'studie'},
{id:'rezeption',title:'Rezeption im Streit',intro:'Eine Inszenierung kann als Aktivierung des Publikums und als problematische Verengung einer Rechtsfrage gelesen werden. Die Kontroverse ist selbst Lernstoff.',tasks:['Lies den SRF-Beitrag und fasse seine Darstellung der Publikumsrolle in eigenen Worten zusammen.','Lies, sofern zugänglich, Fischers ZEIT-Kolumne. Notiere eine konkrete Kritik mit Fundstelle; übernimm keine nur zugeschriebene Behauptung.','Antworte aus der Perspektive einer Dramaturgin: Welche Vereinfachung darf Kunst vornehmen, wann wird sie problematisch?'],model:'Ein begründetes Urteil unterscheidet die ästhetische Leistung einer Versuchsanordnung von der juristischen Vollständigkeit. Kritik kann gerade zeigen, welche Fragen der Text produktiv eröffnet und welche er schliesst.',source:'srf'}
];

